

import { createRoot } from "react-dom/client";
import { createBrowserRouter, RouterProvider} from "react-router";
import App from "./App";
import { AllData } from "./Data/AllData";
import ScrollToTop from "react-scroll-to-top";
import AllCompo from "./components/AllCompo";
import AllProperties from "./Properties/AllProperties";
import AllPropertyDetails from "./PropertyDetails/AllPropertyDetails";
import AllContact from "./ContactUs/AllContact";





const router = createBrowserRouter([
  {
    path: "/",
    element: <App/>,
  },
  {
    path: "properties",
    element: <AllProperties/>,
  },
  {
    path: "details",
    element: <AllPropertyDetails/>,
  },
  {
    path: "contact",
    element: <AllContact/>,
  },

]);

createRoot(document.getElementById("root")).render(
    <AllData>
      <ScrollToTop/>
      <RouterProvider router={router} />
    </AllData>
      

);

