import React, { useEffect } from 'react';

function Banner() {
  useEffect(() => {
    const initCarousel = () => {
      const $ = window.$;
      if ($ && $.fn && $.fn.owlCarousel) {
        const $banner = $('.owl-banner');
        if ($banner.length) {
          if ($banner.hasClass('owl-loaded')) {
            $banner.trigger('destroy.owl.carousel');
            $banner.removeClass('owl-loaded');
          }
          $banner.owlCarousel({
            center: true,
            items: 1,
            loop: true,
            nav: true,
            dots: true,
            navText: [
              '<i class="fa fa-angle-left" aria-hidden="true"></i>',
              '<i class="fa fa-angle-right" aria-hidden="true"></i>'
            ],
            margin: 30,
            responsive: {
              992: {
                items: 1
              },
              1200: {
                items: 1
              }
            }
          });
        }
      }
    };

    initCarousel();

    return () => {
      const $ = window.$;
      if ($ && $.fn && $.fn.owlCarousel) {
        $('.owl-banner').trigger('destroy.owl.carousel');
      }
    };
  }, []);

  return (
    <div>
      <div className="main-banner">
        <div className="owl-carousel owl-banner">
          <div className="item item-1">
            <div className="header-text">
              <span className="category">
                Toronto, <em>Canada</em>
              </span>
              <h2>
                Hurry!
                <br />
                Get the Best Villa for you
              </h2>
            </div>
          </div>

          <div className="item item-2">
            <div className="header-text">
              <span className="category">
                Melbourne, <em>Australia</em>
              </span>
              <h2>
                Be Quick!
                <br />
                Get the best villa in town
              </h2>
            </div>
          </div>

          <div className="item item-3">
            <div className="header-text">
              <span className="category">
                Miami, <em>South Florida</em>
              </span>
              <h2>
                Act Now!
                <br />
                Get the highest level penthouse
              </h2>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Banner;
